/**
 * What counts as "native" when deciding whether an app binary can be
 * reused — read by @expo/fingerprint (scripts/native) and by EAS.
 *
 * Left out, because they change without the binary changing:
 * - ios/ and android/: generated by prebuild from app.config.ts and the
 *   installed packages (gitignored); their inputs are already hashed.
 * - Build output inside native modules: Gradle compiles each module in
 *   node_modules/<pkg>/android, leaving build/, .cxx/ and .gradle/ there —
 *   hashing them made every Android build change the fingerprint.
 * - package.json scripts and .gitignore: they never reach the binary.
 *
 * @type {import('@expo/fingerprint').Config}
 */
const { SourceSkips } = require("@expo/fingerprint");

module.exports = {
  ignorePaths: [
    "ios",
    "ios/**/*",
    "android",
    "android/**/*",
    "**/android/build/**/*",
    "**/android/.cxx/**/*",
    "**/android/.gradle/**/*",
    "**/ios/build/**/*",
  ],
  sourceSkips: SourceSkips.PackageJsonScriptsAll | SourceSkips.GitIgnore,
};
